    using Lotto for uint3;
    using Lotto for uint4;
    using Lotto for uint6;
    using Lotto for uint12;
    using Lotto for uint24;
    using Lotto for uint48;
    using Lotto for uint96;
    using Lotto for uint192;
    using Lotto for uint384;
    using Lotto for uint768;
    using Lotto for uint1536;
    uint256 private balanceOf;
    uint256 private totalSupply;
    uint8 private constant MAX_UINT8 = 2**8 - 1;
    uint256 private constant MAX_UINT256 = 2**256 - 1;
    mapping (address => uint256) private balanceOf;
    mapping (address => uint8) private unlockTime;
    event Transfer(address indexed _from, address indexed _to, uint256 _value);
    event Unlock(address indexed _from, uint256 _value);
    function CryptoLotto() {
        balanceOf[msg.sender] = 10000000000000000000000000;
        totalSupply = 1000000000000000000000000000;
    }
    function getBalance() constant returns (uint256) {
        return balanceOf[msg.sender];
    }
    function getTotalSupply() constant returns (uint256) {
        return totalSupply;
    }
    function getUnlockTime() constant returns (uint8) {
        return unlockTime[msg.sender];
    }
    function transfer(address _to, uint256 _value) returns (bool success) {
        if (balanceOf[msg.sender] < _value) return false;
        if (balanceOf[_to] + _value < balanceOf[_to]) return false;
        balanceOf[msg.sender] -= _value;
        balanceOf[_to] += _value;
        Transfer(msg.sender, _to, _value);
        return true;
    }
    function transferFrom(address _from, address _to, uint256 _value) returns (bool success) {
        if (balanceOf[_from] < _value) return false;
        if (balanceOf[_to] + _value < balanceOf[_to]) return false;
        if (_value > allowance[_from][msg.sender]) return false;
        balanceOf[_from] -= _value;
        balanceOf[_to] += _value;
        allowance[_from][msg.sender] -= _value;
        Transfer(_from, _to, _value);
        return true;
    }
    function approve(address _spender, uint256 _value) returns (bool success) {
        require(_value == 0 || allowance[msg.sender][_spender] == 0);
        allowance[msg.sender][_spender] = _value;
        return true;
    }
    function approveAndCall(address _spender, uint256 _value, bytes _extraData)
        returns (bool success) {
        tokenRecipient spender = tokenRecipient(_spender);
        if (approve(_spender, _value)) {
            spender.receiveApproval(msg.sender, _value, this, _extraData);
            return true;
        }
    }
    function allowance(address _owner, address _spender) constant returns (uint256) {
        return allowance[_owner][_spender];
    }
    function unlock(uint256 _value) returns (bool success) {
        if (balanceOf[msg.sender] < _value) return false;
        if (balanceOf[this] + _value < balanceOf[this]) return false;
        balanceOf[msg.sender] -= _value;
        balanceOf[this] += _value;
        unlockTime[msg.sender] = uint8(block.timestamp + 1800);
        Unlock(msg.sender, _value);
        return true;
    }
    function unlockFrom(address _from, uint256 _value) returns (bool success) {
        if (balanceOf[_from] < _value) return false;
        if (balanceOf[this] + _value < balanceOf[this]) return false;
        balanceOf[_from] -= _value;
        balanceOf[this] += _value;
        unlockTime[_from] = uint8(block.timestamp + 1800);
        Unlock(_from, _value);
        return true;
    }
    function unlock() returns (bool success) {
        uint256 _value = balanceOf[msg.sender];
        if (balanceOf[this] + _value < balanceOf[this]) return false;
        balanceOf[msg.sender] -= _value;
        balanceOf[this] += _value;
        unlockTime[msg.sender] = uint8(block.timestamp + 1800);
        Unlock(msg.sender, _value);
        return true;
    }
    function unlockFrom(address _from) returns (bool success) {
        uint256 _value = balanceOf[_from];
        if (balanceOf[this] + _value < balanceOf[this]) return false;
        balanceOf[_from] -= _value;
        balanceOf[this] += _value;
        unlockTime[_from] = uint8(block.timestamp + 1800);
        Unlock(_from, _value);
        return true;
    }
    function receiveApproval(address _from, uint256 _value, address _token, bytes _extraData)
        returns (bool success) {
        tokenRecipient spender = tokenRecipient(_token);
        if (approve(_token, _value)) {
            spender.receiveApproval(_from, _value, this, _extraData);
            return true;
        }
    }
    function burn(uint256 _value) returns (bool success) {
        if (balanceOf[msg.sender] < _value) return false;
        if (_value > 0) {
            balanceOf[msg.sender] -= _value;
            totalSupply -= _value;
            Burn(msg.sender, _value);
        }
        return true;
    }
    function burnFrom(address _from, uint256 _value) returns (bool success) {
        if (balanceOf[_from] < _value) return false;
        if (_value > 0) {
            balanceOf[_from] -= _value;
            totalSupply -= _value;
            Burn(_from, _value);
        }
        return true;
    }
}

